'use strict';
(()=>{
const $=s=>document.querySelector(s);
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeJSON=v=>{try{return JSON.parse(v);}catch{return null;}};
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const uid=()=>globalThis.crypto?.randomUUID?.()||`flora-${Date.now()}-${Math.random().toString(36).slice(2,12)}`;
const MONTHS=['一月','二月','三月','四月','五月','六月','七月','八月','九月','十月','十一月','十二月'];
const PLANTS=[
{id:'osmanthus',name:'桂花',latin:'Osmanthus fragrans',family:'木犀科 · 木犀属',months:[9,10],color:'#d7a34b',image:'osmanthus',description:'秋日里最先被闻到的花。细小的花朵藏在叶腋间，金桂、银桂和丹桂各有不同的色泽与香气。',features:'常绿灌木或小乔木；叶片对生、革质；小花簇生，花冠四裂，香气浓郁。',habitat:'喜温暖湿润、阳光充足的环境，常见于江南庭院、公园及行道绿地。'},
{id:'chrysanthemum',name:'菊花',latin:'Chrysanthemum × morifolium',family:'菊科 · 菊属',months:[10,11],color:'#bc9855',image:'chrysanthemum',description:'一朵菊花，其实是许多小花组成的头状花序。秋菊的花色、瓣形千变万化，是深秋公园里的主角。',features:'多年生草本；叶片互生并有裂片；头状花序，园艺品种花形丰富。',habitat:'喜阳光与通风，适宜疏松、排水良好的土壤。'},
{id:'rose',name:'月季',latin:'Rosa chinensis',family:'蔷薇科 · 蔷薇属',months:[4,5,6,10],color:'#b77b81',image:'rose',description:'被称作花中皇后，常能多季开花。春末与秋季通常是上海月季更值得期待的观赏时段。',features:'常绿或半常绿灌木，枝条常有皮刺；奇数羽状复叶；花色与花型多样。',habitat:'喜光，适宜通风良好、日照充足的花园。'},
{id:'cherry',name:'樱花',latin:'Prunus × yedoensis',family:'蔷薇科 · 李属',months:[3,4],color:'#d3a9ac',image:'cherry',description:'樱花是多种樱类植物的统称，开花时间随品种而异。粉白花簇铺满枝头，是春天短暂而明亮的相遇。',features:'落叶乔木，叶缘有锯齿；常见品种花瓣五枚，也有重瓣品种。',habitat:'多见于温带地区的公园、庭院与山坡。'},
{id:'magnolia',name:'白玉兰',latin:'Magnolia denudata',family:'木兰科 · 木兰属',months:[2,3],color:'#b9ba98',image:'magnolia',description:'上海的市花。早春先花后叶，洁白的花朵立在枝端，像一盏盏迎接春天的小灯。',features:'落叶乔木；早春花先于叶开放；花被片白色，花朵较大。',habitat:'喜阳光，适宜肥沃、排水良好的微酸性土壤。'},
{id:'lotus',name:'荷花',latin:'Nelumbo nucifera',family:'莲科 · 莲属',months:[6,7,8],color:'#c68e9d',image:'lotus',description:'叶片如伞，花朵挺出水面。盛夏的荷塘适合清晨来访，观察花、叶与莲蓬的不同形态。',features:'多年生水生草本；盾状圆叶；花单生于花梗顶端；果实聚生于莲蓬中。',habitat:'生长于相对平静、阳光充足的池塘与浅水湖泊。'}
];
const PLACES=[
{id:'guilin',name:'桂林公园',address:'上海市徐汇区桂林路128号',lat:31.1674,lng:121.4177,plants:['osmanthus'],description:'循着桂香，走进江南园林的亭台与长廊。',source:'https://www.shanghai.gov.cn/nw17239/20261016/7d8c24e5ec1b4fc89e5d2e18c983d9c8.html',sourceName:'上海市政府 · 赏桂指南'},
{id:'gucun',name:'顾村公园',address:'上海市宝山区沪太路4788号',lat:31.3467,lng:121.3734,plants:['osmanthus','rose','cherry'],description:'春日看樱，秋日闻桂，也别错过悦林湖畔的月季。',source:'https://www.shanghai.gov.cn/nw17239/20261016/7d8c24e5ec1b4fc89e5d2e18c983d9c8.html',sourceName:'上海市政府 · 赏桂指南'},
{id:'chenshan',name:'辰山植物园',address:'上海市松江区辰花公路3888号',lat:31.0768,lng:121.1793,plants:['osmanthus','rose','cherry','magnolia'],description:'在月季岛、木兰园与林间小路，读懂植物的四季。',source:'https://lhsr.sh.gov.cn/ywdt/20250321/479b60bd-b378-4fc9-9e34-1364a50ad4af.html',sourceName:'上海绿化市容 · 辰山赏花地图'},
{id:'botanical',name:'上海植物园',address:'上海市徐汇区龙吴路1111号',lat:31.1477,lng:121.4423,plants:['osmanthus'],description:'慢慢走进植物园，寻找藏在绿叶间的秋日小花。',source:'https://www.shanghai.gov.cn/nw17239/20261016/7d8c24e5ec1b4fc89e5d2e18c983d9c8.html',sourceName:'上海市政府 · 赏桂指南'},
{id:'gongqing',name:'共青森林公园',address:'上海市杨浦区军工路2000号',lat:31.3228,lng:121.5486,plants:['chrysanthemum'],description:'在森林、草坪与水岸之间，邂逅秋日菊花。',source:'https://www.shanghai.gov.cn/nw17239/20261026/7626eef747da4898bca00957e3f30b8e.html',sourceName:'上海市政府 · 菊花展示活动'},
{id:'fuxing',name:'复兴公园',address:'上海市黄浦区皋兰路2号甲',lat:31.2151,lng:121.4661,plants:['chrysanthemum'],description:'市中心的一段秋日散步，把赏菊加入午后的行程。',source:'https://www.shanghai.gov.cn/nw17239/20261026/7626eef747da4898bca00957e3f30b8e.html',sourceName:'上海市政府 · 菊花展示活动'}
];
PLACES.push({id:'guyi',name:'古猗园',address:'上海市嘉定区沪宜公路218号',lat:31.2911,lng:121.3122,plants:['lotus'],description:'在古典亭台和曲水之间，遇见夏日荷风。',source:'https://lhsr.sh.gov.cn/gyhd/20260629/3644b8f9-0548-474d-a1a9-eee73d8aa1eb.html',sourceName:'上海绿化市容 · 荷花睡莲展'});
const PLANT_SOURCES={
  gucun:{rose:{url:'https://whlyj.sh.gov.cn/gqfc/20210430/7a1b927cf746442fb11e5064efecf949.html',name:'上海文旅 · 顾村公园月季'},cherry:{url:'https://www.shanghai.gov.cn/nw17239/20260305/99754d1367d544d9b99ab26b4be91ac2.html',name:'上海市政府 · 樱花节'}},
  chenshan:{osmanthus:{url:'https://lhsr.sh.gov.cn/shhx/20221025/0f46fca6a9c64e54810207a8403da867.html',name:'上海绿化市容 · 辰山桂花'}}
};
function placeSource(p){const id=S.plantFilter==='all'?p.matching[0]:S.plantFilter;return PLANT_SOURCES[p.id]?.[id]||{url:p.source,name:p.sourceName};}
const CITIES=[{name:'上海',lat:31.2304,lng:121.4737},{name:'杭州',lat:30.2741,lng:120.1551},{name:'苏州',lat:31.2989,lng:120.5853},{name:'北京',lat:39.9042,lng:116.4074}];
const TABS=[{id:'discover',icon:'compass',label:'发现植物',title:'与自然，再近一点',intro:'认识一株植物，也为生活发现一处新的风景。'},{id:'map',icon:'pin',label:'附近赏花',title:'跟着花期，去散步',intro:'在对的时节，遇见身边正在发生的美好。'},{id:'records',icon:'book',label:'我的手记',title:'收藏每一次相遇',intro:'让偶然遇见的一花一叶，成为长久的记忆。'},{id:'library',icon:'sprout',label:'植物图鉴',title:'翻开一本自然之书',intro:'从名字开始，认识身边熟悉又陌生的植物。'}];
const imageOf=p=>ASSETS[p.image]||ASSETS.hero;
const labelMonths=m=>m.length?m.map(x=>x+'月').join('、'):'花期待补充';
function distance(a,b){const rad=x=>x*Math.PI/180,dlat=rad(b.lat-a.lat),dlng=rad(b.lng-a.lng),v=Math.sin(dlat/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dlng/2)**2;return 12742*Math.atan2(Math.sqrt(v),Math.sqrt(Math.max(0,1-v)));}
function matchPlant(latin){const v=latin.toLowerCase().replaceAll('×','').replace(/\s+/g,' ').trim();return PLANTS.find(p=>v.includes(p.latin.toLowerCase().replaceAll('×','').replace(/\s+/g,' ').trim())||(p.id==='chrysanthemum'&&v.includes('chrysanthemum'))||(p.id==='cherry'&&v.includes('yedoensis')));}
const S={tab:'discover',month:new Date().getMonth()+1,year:new Date().getFullYear(),location:{...CITIES[0],exact:false},radius:50,plantFilter:'all',onlySaved:false,query:'',records:[],db:null,storageError:'',modal:null,selectedPlant:'osmanthus',selectedPlace:'guilin',selectedRecord:null,provider:'deepseek',services:{deepseek:{apiKey:'',endpoint:Recognition.DEEPSEEK_ENDPOINT,model:Recognition.DEEPSEEK_MODEL,verified:false},plantnet:{apiKey:'',proxy:'',verified:false}},settingsDraft:null,busy:false,locating:false,upload:null,error:'',customLocation:{name:'',lat:'',lng:''}};
function currentConfig(){return S.services[S.provider];}
function serviceName(provider=S.provider){return provider==='deepseek'?'DeepSeek':'Pl@ntNet';}
function methodLabel(method){return method==='manual'?'手动记录':method==='deepseek'?'DeepSeek 识别':'Pl@ntNet 识别';}
function captureSettingsDraft(){const draft=S.settingsDraft;if(!draft)return;const cfg=draft.services[draft.provider],key=$('#api-key')?.value??cfg.apiKey;const updated=draft.provider==='deepseek'?{apiKey:key,endpoint:$('#deepseek-endpoint')?.value??cfg.endpoint,model:$('#deepseek-model')?.value??cfg.model}:{apiKey:key,proxy:$('#proxy-url')?.value??cfg.proxy};if(Object.entries(updated).some(([k,v])=>cfg[k]!==v))cfg.verified=false;Object.assign(cfg,updated);}
function applySettings(){captureSettingsDraft();const draft=S.settingsDraft,provider=draft.provider;const updates={};for(const id of ['deepseek','plantnet']){let normalized;try{normalized=Recognition.config(id,draft.services[id]);}catch(e){throw new Error(serviceName(id)+'：'+e.message);}const old=S.services[id],unchanged=Object.entries(normalized).every(([key,value])=>old[key]===value);updates[id]={...normalized,verified:unchanged&&old.verified};}S.services=updates;const normalized=updates[provider];S.provider=provider;S.settingsDraft=null;render();if(S.upload?.photo)openModal('upload');else closeModal();toast(normalized.apiKey?serviceName(provider)+' 配置已应用，首次识别时验证可用性。':'已清除 '+serviceName(provider)+' 的本次会话密钥。');}
try{const loc=safeJSON(localStorage.getItem('flora-location-v1'));if(loc&&CITIES.some(c=>c.name===loc.name))S.location={...CITIES.find(c=>c.name===loc.name),exact:false};}catch{}
let toastTimer;
function toast(message){clearTimeout(toastTimer);$('#toast').innerHTML=icon('check')+`<span>${esc(message)}</span><button data-action="dismiss-toast" aria-label="关闭提示">${icon('x')}</button>`;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,5500);}
function seasonPlants(){return PLANTS.filter(p=>p.months.includes(S.month));}
function nearby(){const saved=new Set(S.records.map(r=>r.plantId));return PLACES.map(p=>({...p,distance:distance(S.location,p),matching:p.plants.filter(id=>PLANTS.find(v=>v.id===id)?.months.includes(S.month)&&(S.plantFilter==='all'||id===S.plantFilter)&&(!S.onlySaved||saved.has(id)))})).filter(p=>p.distance<=S.radius&&p.matching.length).sort((a,b)=>a.distance-b.distance);}
const amap=p=>`https://uri.amap.com/search?keyword=${encodeURIComponent(p.name+' '+p.address)}&view=map&src=flora`;
function noPlaces(){return `<div class="empty small">${icon('pin')}<h3>暂未收录符合条件的地点</h3><p>可扩大距离、切换月份或取消筛选。<br>目前已核实的赏花地点覆盖上海。</p><a href="https://uri.amap.com/search?keyword=${encodeURIComponent(S.location.name+' '+(PLANTS.find(p=>p.id===S.plantFilter)?.name||'赏花 公园'))}&view=map&src=flora" target="_blank" rel="noreferrer">联网后在高德地图继续寻找 ${icon('up')}</a></div>`;}
function placeList(limit){const list=nearby();return `<div class="place-list">${list.length?list.slice(0,limit).map((p,i)=>`<button class="place-item ${S.selectedPlace===p.id?'chosen':''}" data-action="place" data-id="${p.id}"><span class="place-number">${String(i+1).padStart(2,'0')}</span><div><h3>${p.name}${icon('up')}</h3><p>${p.matching.map(id=>PLANTS.find(v=>v.id===id)?.name).join(' · ')}</p></div><span class="distance">${p.distance.toFixed(1)}<small>km</small></span></button>`).join(''):noPlaces()}</div>`;}
function plantCard(p){return `<button class="plant-card" data-action="plant" data-id="${p.id}"><div class="plant-photo"><img src="${imageOf(p)}" alt="${p.name}" loading="lazy"><span class="photo-badge"><i></i>${p.months.includes(S.month)?'常见花期':'等待花开'}</span><span class="photo-arrow">${icon('up')}</span></div><div class="plant-caption"><div><h3>${p.name}</h3><i>${p.latin}</i></div><span class="plant-month">${p.months.includes(S.month)?S.month+'月可赏':labelMonths(p.months)}</span></div></button>`;}
function heading(){const tab=TABS.find(t=>t.id===S.tab),season=S.month>=9&&S.month<=11?'秋日观察':S.month>=3&&S.month<=5?'春日观察':S.month>=6&&S.month<=8?'夏日观察':'冬日观察';return `<div class="page-heading"><div><div class="eyebrow">A LITTLE CLOSER TO NATURE</div><h1>${tab.title}<span class="heading-dot">.</span></h1><p>${tab.intro}</p></div><div class="heading-date"><span>${String(S.month).padStart(2,'0')}</span><div>${MONTHS[S.month-1]}<small>${S.year} · ${season}</small></div>${icon('flower')}</div></div>`;}
function footer(){return `<footer><span>${icon('flower')}花间 FLORA NOTES</span><p>让每一次看见，都成为一次相遇。</p><button data-action="about">观察须知 ${icon('up')}</button></footer>`;}
function discover(){const seasonal=seasonPlants();return `<div class="discover-layout"><div class="discover-main"><section class="hero"><img src="${ASSETS.hero}" alt="层叠生长的绿色蕨叶"><div class="hero-shade"></div><div class="hero-copy"><span><i></i>留一点时间给自然</span><h2>万物有名，<br>相遇有记。</h2><p>从一张照片开始，<br>认识身边的一花一叶。</p><button data-action="upload">发现我的第一株植物 ${icon('up')}</button></div><div class="hero-index">FIELD NOTES <span>—</span> NO. 001</div><div class="hero-corner">${icon('leaf')}<span>看见 · 认识 · 记录</span></div></section><section class="upload-section"><div class="section-title"><div><span class="tiny-label">MEET A NEW PLANT</span><h2>这是什么植物？<span class="section-line"></span></h2></div><span class="subtle">让好奇心，成为出发的理由</span></div><div class="upload-box" data-drop-zone><button class="upload-target" data-action="choose-photo"><span class="upload-icon">${icon('image')}<i>${icon('plus')}</i></span><h3>上传照片，认识一株植物</h3><p>将照片拖到这里，或 <b>点击选择照片</b></p><small>JPG / PNG / WebP · 最大 10 MB</small></button><div class="upload-steps">${[{n:'01',title:'拍下身边的绿意',text:'清晰拍摄花朵、叶片或整株植物'},{n:'02',title:'认识它的名字',text:'连接识别接口，或手动选择植物'},{n:'03',title:'留下相遇的坐标',text:'保存手记，寻找附近的赏花地'}].map(s=>`<div><span>${s.n}</span><div><h4>${s.title}</h4><p>${s.text}</p></div></div>`).join('')}</div></div><div class="upload-footnote">${icon('shield')}<span>照片与手记仅存本机，记得导出备份</span><button data-action="settings"><i></i>${currentConfig().apiKey?serviceName()+(currentConfig().verified?' · 已验证':' · 待验证'):'配置识别接口'}${icon('up')}</button></div></section><section><div class="section-title"><div><span class="tiny-label">IN SEASON</span><h2>此刻，花正好</h2></div><button class="text-button" data-action="nav" data-tab="library">翻阅植物图鉴 ${icon('arrow')}</button></div><div class="plant-grid">${seasonal.length?seasonal.slice(0,3).map(plantCard).join(''):`<div class="empty">${icon('flower')}<h3>这个月，适合期待下一次花开</h3><p>翻阅图鉴，提前计划你的赏花时节。</p></div>`}</div><p class="data-note">按上海地区常见花期推荐，实际花况随天气和品种变化。</p></section></div><aside class="right-rail"><section class="season-panel"><div class="rail-title">${icon('calendar')}<h3>花开有时</h3><span>CALENDAR</span></div><div class="month-control"><button data-action="prev-month" aria-label="上个月">${icon('left')}</button><span>${S.year}<b>${MONTHS[S.month-1]}</b></span><button data-action="next-month" aria-label="下个月">${icon('right')}</button></div><div class="month-grid">${MONTHS.map((m,i)=>`<button data-action="month" data-month="${i+1}" class="${i+1===S.month?'selected':''}" aria-pressed="${i+1===S.month}">${m}<i class="${PLANTS.some(p=>p.months.includes(i+1))?'has-bloom':''}"></i></button>`).join('')}</div><div class="calendar-divider"></div><p class="rail-subtitle">本月值得留意</p><div class="bloom-list">${seasonal.map(p=>`<button data-action="plant" data-id="${p.id}"><span class="bloom-dot" style="background:${p.color}"></span>${p.name}<small>${p.id==='rose'&&S.month===10?'秋日再开':'常见花期'}</small></button>`).join('')||'<span class="subtle">等待下一次花开。</span>'}</div><span class="rail-note">花期是自然的约定，也有天气的小变数。</span></section><section class="nearby-panel"><div class="rail-title">${icon('pin')}<h3>赴一场花的约</h3></div><div class="reference-point"><i></i>${S.location.exact?'距参考坐标':'距'+esc(S.location.name)+'市中心'} · ${S.radius} km 内</div>${placeList(3)}<button class="map-link" data-action="nav" data-tab="map">查看附近赏花地 ${icon('arrow')}</button></section><div class="quote-card"><span>“</span><p>草木有本心，<br>何求美人折。</p><small>— 张九龄《感遇》</small>${icon('sprout')}</div></aside></div>`;}
function library(){return `<div class="toolbar"><div class="search-field">${icon('search')}<input id="plant-search" aria-label="搜索植物" placeholder="搜索植物名称、学名或科属" value="${esc(S.query)}"></div><span class="subtle">收录 ${PLANTS.length} 种常见植物</span></div><div class="library-grid" id="library-grid">${plantResults()}</div><p class="data-note">图鉴为观察入门；花期为上海地区季节参考。照片为物种示意，不同品种可能有所差别。</p>`;}
function plantResults(){const ps=PLANTS.filter(p=>(p.name+p.latin+p.family).toLowerCase().includes(S.query.toLowerCase()));return ps.length?ps.map(plantCard).join(''):`<div class="empty">${icon('search')}<h3>还没有收录这株植物</h3><p>可以手动输入名称，建立自己的植物记录。</p><button class="primary" data-action="upload">记录新植物 ${icon('plus')}</button></div>`;}
function records(){return `<div class="records-stats"><div>${icon('book')}<span>自然手记<b>${S.records.length}<small>篇</small></b></span></div><div>${icon('sprout')}<span>认识植物<b>${new Set(S.records.map(r=>r.scientificName||r.plantName)).size}<small>种</small></b></span></div><div>${icon('pin')}<span>留下足迹<b>${new Set(S.records.map(r=>r.address)).size}<small>处</small></b></span></div></div><div class="toolbar"><div class="search-field">${icon('search')}<input id="record-search" aria-label="搜索手记" placeholder="搜索植物、发现地点或笔记" value="${esc(S.query)}"></div><div class="record-actions"><button class="secondary" data-action="import">${icon('upload')}导入备份</button><button class="secondary" data-action="export" ${S.records.length?'':'disabled'}>${icon('download')}导出备份</button></div></div><div class="record-grid" id="record-grid">${recordResults()}</div><p class="data-note">记录保存在此浏览器的本地数据库中，清理网站数据、更换浏览器或移动 HTML 文件可能影响访问。导出备份包含照片与地点，可重新导入。</p>`;}
function recordResults(){const rows=S.records.filter(r=>(r.plantName+r.address+r.notes+r.scientificName).toLowerCase().includes(S.query.toLowerCase()));return rows.length?rows.map(r=>`<article class="record-card"><button class="record-open" data-action="record" data-id="${esc(r.id)}"><img src="${r.photo}" alt="${esc(r.plantName)}" loading="lazy"><span class="record-type">${methodLabel(r.method)}</span><div><small>${esc(r.observedAt)}</small><h3>${esc(r.plantName)}</h3><i>${esc(r.scientificName)}</i><p>${icon('pin')}${esc(r.address)}</p></div></button><button class="record-delete" data-action="delete" data-id="${esc(r.id)}" aria-label="删除${esc(r.plantName)}手记">${icon('trash')}</button></article>`).join(''):`<div class="empty records-empty">${icon('sprout')}<span class="tiny-label">YOUR OWN FIELD NOTES</span><h2>${S.query?'没有找到匹配的手记':'第一篇手记，从今天开始'}</h2><p>${S.query?'试试其他植物名称或地点。':'拍一朵花、一片叶，把日常里的小小发现收藏起来。'}</p><button class="primary" data-action="choose-photo">上传植物照片 ${icon('plus')}</button>${!S.query?'<button class="text-button" data-action="import" style="display:flex;margin:19px auto 0">已有备份？点击导入</button>':''}</div>`;}
function mapPage(){const list=nearby(),active=list.find(p=>p.id===S.selectedPlace)||list[0];return `<div class="map-filterbar"><div class="filter-group">${icon('settings')}<select id="filter-plant" aria-label="筛选植物"><option value="all">全部植物</option>${PLANTS.map(p=>`<option value="${p.id}" ${S.plantFilter===p.id?'selected':''}>${p.name}</option>`).join('')}</select><select id="filter-month" aria-label="筛选月份">${MONTHS.map((m,i)=>`<option value="${i+1}" ${S.month===i+1?'selected':''}>${m}</option>`).join('')}</select><select id="filter-radius" aria-label="附近距离">${[5,10,20,50,100].map(r=>`<option value="${r}" ${S.radius===r?'selected':''}>${r} km 内</option>`).join('')}</select></div><label class="check-label"><input type="checkbox" id="only-saved" ${S.onlySaved?'checked':''}>只看我记录过的植物</label></div><div class="map-layout"><section class="map-results"><div class="map-result-title"><h2>${list.length} 处赏花地</h2><small>${S.location.exact?'以参考坐标计算距离':'以'+esc(S.location.name)+'市中心为参考'}</small></div>${placeList()}${active?`<div class="place-details"><span class="tiny-label">NEXT STOP</span><h3>${active.name}</h3><p>${active.description}</p><p class="place-address">${icon('pin')}${active.address}</p><div class="place-tags">${active.matching.map(id=>`<span>${PLANTS.find(p=>p.id===id)?.name} · 常见花期</span>`).join('')}</div><a class="primary" href="${amap(active)}" target="_blank" rel="noreferrer">在高德地图中查看（需联网） ${icon('up')}</a><a class="source-link" href="${placeSource(active).url}" target="_blank" rel="noreferrer">资料来源：${placeSource(active).name} ${icon('up')}</a></div>`:''}</section><section class="botanical-map">${drawMap(list,active)}</section></div><p class="data-note">距离为直线距离，地点坐标为参考点；目前已核实地点覆盖上海。离线地图为位置示意，不含道路导航。出发前请查看园方最新花况。</p>`;}
function drawMap(list,active){const all=[S.location,...list],minLat=Math.min(...all.map(p=>p.lat)),maxLat=Math.max(...all.map(p=>p.lat)),minLng=Math.min(...all.map(p=>p.lng)),maxLng=Math.max(...all.map(p=>p.lng));const pos=p=>`left:${15+(p.lng-minLng)/(maxLng-minLng||1)*70}%;top:${26+(maxLat-p.lat)/(maxLat-minLat||1)*53}%`;return `<div class="map-paper"><div class="map-grid-lines"></div><svg class="map-drawing" viewBox="0 0 600 650" preserveAspectRatio="none" aria-hidden="true"><path d="M470,-30 C335,100 570,145 409,280 C330,350 460,370 359,480 S420,600 320,690" fill="none" stroke="#ccd9cb" stroke-width="58"/><path d="M470,-30 C335,100 570,145 409,280 C330,350 460,370 359,480 S420,600 320,690" fill="none" stroke="#e1e9dc" stroke-width="43"/>${[100,200,300,400,500].map(n=>`<path d="M-30 ${n} Q230 ${n-65},650 ${n+40}" fill="none" stroke="#fffdf5" stroke-width="9"/><path d="M${n} -30 Q${n+80} 280,${n-30} 690" fill="none" stroke="#fffdf5" stroke-width="7"/>`).join('')}<ellipse cx="140" cy="180" rx="60" ry="35" fill="#d4dcc1"/><ellipse cx="470" cy="500" rx="60" ry="70" fill="#d4dcc1"/></svg><div class="map-heading"><span class="tiny-label">A WALK AMONG FLOWERS</span><h3>${esc(S.location.name)} · 寻花地图</h3><p>赏花地点位置示意</p></div><div class="map-north">N<span>↑</span></div>${list.map(p=>`<button class="map-pin ${active?.id===p.id?'active':''}" style="${pos(p)}" data-action="place" data-id="${p.id}" aria-label="${p.name}">${icon('flower')}<span>${p.name}</span></button>`).join('')}<div class="you-pin" style="${pos(S.location)}"><i></i><span>${S.location.exact?'参考位置':'城市中心'}</span></div><div class="map-legend"><i></i>赏花地点 <b></b>参考位置</div><div class="map-caption">按经纬度分布绘制 · 背景为装饰示意</div></div>`;}
function render(){const label=TABS.find(t=>t.id===S.tab).label;$('#nav').innerHTML=TABS.map(n=>`<button class="${S.tab===n.id?'active':''}" data-action="nav" data-tab="${n.id}" ${S.tab===n.id?'aria-current="page"':''}>${icon(n.icon)}<span>${n.label}</span>${n.id==='records'?`<small>${S.records.length}</small>`:''}${S.tab===n.id?'<i></i>':''}</button>`).join('');$('#breadcrumb-label').textContent=label;$('#location-label').textContent=S.location.name;$('#api-indicator').classList.toggle('ready',currentConfig().verified);$('#main').innerHTML=(S.storageError?`<div class="storage-banner">${esc(S.storageError)} <button data-action="import">导入备份</button></div>`:'')+heading()+({discover,library,records,map:mapPage}[S.tab]())+footer();}
function go(tab){S.tab=tab;S.query='';closeMenu();render();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function updateMenuAccess(){const el=$('#sidebar');el.inert=matchMedia('(max-width:680px)').matches&&!el.classList.contains('open');}
function closeMenu(){$('#sidebar').classList.remove('open');$('#mobile-backdrop').hidden=true;updateMenuAccess();}
function openModal(type){if(type==='settings')S.settingsDraft={provider:S.provider,services:structuredClone(S.services)};else S.settingsDraft=null;S.modal=type;S.error='';renderModal();if(!$('#dialog').open)$('#dialog').showModal();}
function closeModal(){if(S.busy)return;if(S.modal==='settings')S.settingsDraft=null;S.modal=null;S.error='';$('#dialog').close();}
function errorPanel(){return S.error?`<div class="error" role="alert">${esc(S.error)}</div>`:'';}
function showError(message){S.error=message;const current=$('#modal-error');if(current)current.innerHTML=errorPanel();else renderModal();}
function modalClose(){return `<button class="modal-close" data-action="close-modal" ${S.busy?'disabled':''} aria-label="关闭窗口">${icon('x')}</button>`;}
function settingsModal(){
  const draft=S.settingsDraft,cfg=draft.services[draft.provider],deep=draft.provider==='deepseek';
  return `<span class="tiny-label">CONNECT TO NATURE</span><h2>连接植物识别</h2><p class="modal-intro">识别时需要联网；其他功能都可以离线使用。</p>
  <form id="settings-form"><label class="field-label" for="api-provider">识别服务</label><select id="api-provider"><option value="deepseek" ${deep?'selected':''}>DeepSeek · 图片识别与植物介绍</option><option value="plantnet" ${!deep?'selected':''}>Pl@ntNet · 专业植物候选</option></select>
  <div class="service-card provider-card"><span class="service-icon">${icon('sprout')}</span><div><b>${serviceName(draft.provider)} 植物识别</b><small>${deep?'图片理解 · 中文介绍 · 辨识线索':'植物候选 · 接口匹配分数'}</small></div><span class="service-tag ${cfg.verified?'configured':''}">${cfg.verified?'已验证':cfg.apiKey?'待验证':'待配置'}</span></div>
  <label class="field-label" for="api-key">${serviceName(draft.provider)} API Key</label><input id="api-key" type="password" autocomplete="off" spellcheck="false" placeholder="粘贴你的 ${serviceName(draft.provider)} API Key" value="${esc(cfg.apiKey)}">
  ${deep?`<label class="field-label" for="deepseek-model">图片模型</label><input id="deepseek-model" list="deepseek-models" spellcheck="false" value="${esc(cfg.model)}" placeholder="deepseek-flash" maxlength="120"><datalist id="deepseek-models"><option value="deepseek-flash"></datalist><p class="field-help">默认使用支持图片的 deepseek-flash；自定义模型也必须支持图片输入。</p><label class="field-label" for="deepseek-endpoint">接口地址</label><input id="deepseek-endpoint" type="url" spellcheck="false" value="${esc(cfg.endpoint)}" placeholder="https://api.deepseek.com/chat/completions"><p class="field-help">支持基础地址 https://api.deepseek.com、/v1 地址或完整的 /chat/completions 地址。兼容代理也可填写在这里。</p>`:''}
  <p class="field-help">两个服务的密钥分别保留在当前页面内存中，刷新后清除，不写入记录、HTML 或备份。只有点击识别时，照片才会发送给所选服务。</p>
  <a class="inline-link" href="${deep?'https://platform.deepseek.com/api_keys':'https://my.plantnet.org/'}" target="_blank" rel="noreferrer">联网申请 ${serviceName(draft.provider)} 密钥 ${icon('up')}</a>
  <details class="config-details" ${!deep&&cfg.proxy?'open':''}><summary>${deep?'接口与离线文件的使用说明':'高级设置：识别代理地址（选填）'}</summary>
  ${deep?`<p>采用 Chat Completions 图片请求格式，照片以 Base64 发送，密钥放在 Authorization: Bearer 请求头中。只向模型发送所选照片，不发送发现地点或手记。</p><p>自定义接口需兼容图片请求和 JSON 输出，并允许 CORS 的 Authorization、Content-Type 请求头。</p><a href="https://api-docs.deepseek.com/guides/vision/" target="_blank" rel="noreferrer">DeepSeek 官方图片 API 文档 ↗</a>`:`<label class="field-label" for="proxy-url">兼容 Pl@ntNet 的代理 URL</label><input id="proxy-url" type="url" placeholder="https://你的服务/identify" value="${esc(cfg.proxy)}"><p>留空时直连 Pl@ntNet。代理请求为 POST multipart/form-data，字段 images、organs=auto；密钥以 X-Plantnet-Key 传递；响应保持 Pl@ntNet 的 results 格式。</p>`}
  <p>file:// 离线文件可能受浏览器跨域限制，此时可填写允许 CORS 的兼容接口。仅使用你信任的 HTTPS 地址；本机调试可用 http://localhost。</p></details>
  <div id="modal-error">${errorPanel()}</div><button class="primary full" type="submit">${icon('check')}应用设置</button></form><p class="field-help">应用设置不消耗识别额度；成功返回真实候选后才标记“已验证”。没有密钥也可以手动记录。</p>`;
}
function locationModal(){return `<span class="tiny-label">WHERE NATURE FINDS YOU</span><h2>从哪里出发？</h2><p class="modal-intro">选择参考城市，或授权定位计算附近距离。</p><button class="location-detect" data-action="locate" ${S.locating?'disabled':''}>${icon('locate')}${S.locating?'正在获取位置…':'使用我的当前位置'}${icon('arrow')}</button><label class="field-label">手动选择城市</label><div class="city-grid">${CITIES.map(c=>`<button data-action="city" data-city="${c.name}" class="${c.name===S.location.name?'selected':''}">${c.name}${c.name===S.location.name?icon('check'):''}</button>`).join('')}</div><p class="field-help">手动选城按市中心估算距离。地点库目前覆盖上海，其他城市会显示暂无收录；不会把外地地点当作你的附近推荐。</p><details class="config-details"><summary>手动设置参考坐标（WGS84）</summary><form id="coordinate-form"><label class="field-label" for="custom-location">位置名称</label><input id="custom-location" placeholder="例如：学校门口" maxlength="50"><label class="field-label">纬度 / 经度</label><div class="coordinate-fields"><input id="latitude" aria-label="纬度" type="number" step="any" min="-90" max="90" placeholder="纬度，如 31.2304" required><input id="longitude" aria-label="经度" type="number" step="any" min="-180" max="180" placeholder="经度，如 121.4737" required></div><button class="secondary full" type="submit">使用此位置</button></form></details><p class="field-help">定位需要浏览器支持和授权，完全断网时可能不可用。可以直接选择城市或输入坐标。</p><div id="modal-error">${errorPanel()}</div>`;}
function plantModal(){const p=PLANTS.find(p=>p.id===S.selectedPlant);return `<div class="plant-detail-cover"><img src="${imageOf(p)}" alt="${p.name}"><span>BOTANICAL FIELD GUIDE</span></div><span class="tiny-label">${p.family}</span><h2>${p.name}<span class="detail-status">${p.months.includes(S.month)?'本月为常见花期':'期待下一次花开'}</span></h2><i class="latin-name">${p.latin}</i><p class="plant-description">${p.description}</p><div class="plant-facts"><div>${icon('flower')}<b>常见花期</b><span>${labelMonths(p.months)}</span></div><div>${icon('leaf')}<b>辨识特征</b><p>${p.features}</p></div><div>${icon('sprout')}<b>生长环境</b><p>${p.habitat}</p></div></div><p class="field-help">花期为上海地区参考，实际随品种与气候变化；图片为物种示意。</p><button class="primary full" data-action="find-plant" data-id="${p.id}">寻找附近的${p.name} ${icon('arrow')}</button>`;}
function newUpload(){return {photo:'',file:null,originalName:'',width:0,height:0,candidates:[],candidate:null,resultProvider:null,resultModel:'',manual:true,plantId:'osmanthus',customName:'',customMonths:[],address:'',coordinates:null,notes:'',observedAt:today()};}
function uploadModal(){const u=S.upload||(S.upload=newUpload());return `<span class="tiny-label">A NEW ENCOUNTER</span><h2>记录一株植物</h2><p class="modal-intro">拍下它的模样，也记下你们相遇的地方。</p>${u.photo?`<div class="capture-layout"><div class="capture-photo"><img src="${u.photo}" alt="待记录的植物照片"><button data-action="choose-photo" ${S.busy?'disabled':''}>${icon('image')}更换照片</button></div><div class="capture-form"><div class="identify-actions"><button class="primary" data-action="identify" ${S.busy?'disabled':''}>${icon('sprout')}${S.busy?'正在处理…':'识别这株植物'}</button><button class="text-button" data-action="manual" ${S.busy?'disabled':''}>手动记录</button></div><p class="recognition-provider">识别服务：${serviceName()} · 需联网</p>${!currentConfig().apiKey?'<div class="info-note">识别接口待配置。<button data-action="settings">去设置 ↗</button><br>也可以先选择植物，保存你的发现。</div>':''}${!u.manual&&u.candidate?`<label class="field-label">识别结果 · 请选择最符合的一项</label><div class="candidates">${u.candidates.map((c,i)=>`<button data-action="candidate" data-index="${i}" class="${u.candidate===c?'selected':''}"><span>${esc(c.name)}<small>${esc(c.latin)}</small></span><b>${c.score==null?'候选':(c.score*100).toFixed(1)+'%'}</b></button>`).join('')}</div><p class="field-help">${u.resultProvider==='deepseek'?'DeepSeek 的候选与花期为模型推测，请结合实物核实。':'百分比为 Pl@ntNet 接口匹配分数，请结合实物核实。'}${u.candidate.months.length?'':'该植物花期尚未收录。'}</p><div class="identified-info"><b>${esc(u.candidate.family||'科属信息暂缺')}</b><p>参考花期：${labelMonths(u.candidate.months)}</p>${u.candidate.description?`<p>${esc(u.candidate.description)}</p>`:''}${u.candidate.features?`<p>辨识特征：${esc(u.candidate.features)}</p>`:''}${u.candidate.reason?`<p>照片线索：${esc(u.candidate.reason)}</p>`:''}</div>`:`<label class="field-label" for="manual-plant">植物名称 <em>*</em><span>手动选择</span></label><select id="manual-plant">${PLANTS.map(p=>`<option value="${p.id}" ${u.plantId===p.id?'selected':''}>${p.name} · ${p.latin}</option>`).join('')}<option value="custom" ${u.plantId==='custom'?'selected':''}>其他植物，手动填写</option></select>${u.plantId==='custom'?`<input id="custom-name" value="${esc(u.customName)}" aria-label="其他植物名称" placeholder="请输入植物名称" maxlength="150"><label class="field-label">常见花期（可选）</label><div class="bloom-month-picker">${MONTHS.map((m,i)=>`<button data-action="custom-month" data-month="${i+1}" class="${u.customMonths.includes(i+1)?'selected':''}" aria-pressed="${u.customMonths.includes(i+1)}">${i+1}月</button>`).join('')}</div>`:''}`}
<label class="field-label" for="address">发现地点 <em>*</em><button data-action="locate-upload" ${S.locating?'disabled':''}>${icon('locate')}${S.locating?'定位中':'定位'}</button></label><input id="address" value="${esc(u.address)}" placeholder="例如：上海 · 校园南门的花坛" maxlength="300"><select id="known-place" aria-label="选择已收录的公园"><option value="">或选择已收录的公园…</option>${PLACES.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select><p class="field-help">${u.coordinates?`参考坐标：${u.coordinates.lat.toFixed(5)}, ${u.coordinates.lng.toFixed(5)}`:'手填地址不会自动解析坐标；可选公园或授权定位。'}</p><label class="field-label" for="observed-at">观察日期</label><input id="observed-at" type="date" value="${esc(u.observedAt)}" max="${today()}"><label class="field-label" for="notes">随手记（可选）</label><textarea id="notes" rows="2" placeholder="花的颜色、闻到的香气，或今天的心情…" maxlength="2000">${esc(u.notes)}</textarea></div></div>`:`<button class="modal-upload" data-action="choose-photo" data-drop-zone>${icon('image')}<b>选择或拖入植物照片</b><span>JPG / PNG / WebP · 最大 10 MB</span></button>`}<div id="modal-error">${errorPanel()}</div>${u.photo?`<div class="modal-bottom"><span>${icon('shield')}照片与地点仅保存在此浏览器</span><button class="primary" data-action="save-record" ${S.busy||!S.db?'disabled':''}>${S.busy?'正在处理…':'保存植物手记'} ${icon('arrow')}</button></div>`:''}`;}
function recordModal(){const r=S.records.find(v=>v.id===S.selectedRecord);if(!r)return '';return `<div class="plant-detail-cover"><img src="${r.photo}" alt="${esc(r.plantName)}"><span>MY FIELD NOTES</span></div><span class="tiny-label">${esc(r.observedAt)} · ${methodLabel(r.method)}</span><h2>${esc(r.plantName)}</h2><i class="latin-name">${esc(r.scientificName)}</i>${r.description?`<p class="plant-description">${esc(r.description)}</p>`:''}<div class="plant-facts">${r.family?`<div>${icon('sprout')}<b>科属</b><p>${esc(r.family)}</p></div>`:''}${r.features?`<div>${icon('leaf')}<b>辨识特征</b><p>${esc(r.features)}</p></div>`:''}${r.reason?`<div>${icon('search')}<b>照片线索</b><p>${esc(r.reason)}</p></div>`:''}<div>${icon('pin')}<b>发现地点</b><p>${esc(r.address)}</p></div>${r.latitude!=null?`<p class="field-help">坐标 ${r.latitude.toFixed(5)}, ${r.longitude.toFixed(5)}</p>`:''}<div>${icon('flower')}<b>参考花期</b><p>${labelMonths(r.bloomMonths)}</p></div>${r.notes?`<div>${icon('book')}<b>随手记</b><p class="preserve-lines">${esc(r.notes)}</p></div>`:''}<div>${icon('image')}<b>照片地址</b><p>本机数据库 · ${esc(r.photoAddress)}</p></div></div><button class="inline-link" data-action="download-photo" data-id="${esc(r.id)}">下载已保存的照片 ${icon('download')}</button><p class="field-help">照片地址为本机内部标识，备份会包含完整照片。${r.method==='deepseek'?`DeepSeek 模型：${esc(r.model||'未记录')}；介绍与花期为模型推测，请结合实物核实。`:''}</p><button class="primary full" data-action="find-record" data-id="${esc(r.id)}">寻找附近赏花地 ${icon('arrow')}</button>`;}
function deleteModal(){const r=S.records.find(v=>v.id===S.selectedRecord);return `<span class="tiny-label">YOUR FIELD NOTES</span><h2>删除这次相遇？</h2><p class="modal-intro">“${esc(r?.plantName)}”的手记和照片将从本机数据库删除。</p><div id="modal-error">${errorPanel()}</div><div class="dialog-actions"><button class="secondary" data-action="close-modal" ${S.busy?'disabled':''}>保留手记</button><button class="danger" data-action="confirm-delete" ${S.busy?'disabled':''}>${S.busy?'正在删除…':'确认删除'}</button></div>`;}
function aboutModal(){return `${icon('flower','about-mark')}<span class="tiny-label">FLORA NOTES · OFFLINE EDITION</span><h2>花间，自然就在身边。</h2><p class="plant-description">为日常中的一花一叶留下名字、照片和坐标。让认识自然，成为一件轻松的小事。</p><div class="about-notes"><p><b>离线时，能做什么？</b>查看图鉴与花期、手动记录植物、保存照片与地点、按距离筛选已收录的赏花地、导入导出含照片的备份。图片与样式均内嵌在此文件中。</p><p><b>关于照片识别</b>支持 DeepSeek 与 Pl@ntNet，需要联网和所选服务的密钥。DeepSeek 默认使用 deepseek-flash 分析图片，提供中文介绍与辨识线索；Pl@ntNet 返回植物候选与匹配分数。默认不调用外部服务，只在点击识别时发送照片，不发送发现地点。DeepSeek 的介绍与花期是模型推测，请结合实物核实。</p><p><b>关于花期与地点</b>参考上海市政府与绿化市容部门公开资料，资料整理日期：2026年10月29日。地点详情附来源。花期是常见月份参考，不代表现场实时花况。地点库目前覆盖上海；切换其他城市不会虚构附近推荐。</p><p><b>关于你的数据</b>记录与照片保存在此浏览器的 IndexedDB 中，HTML 文件本身不会被改写。清除浏览器数据、换浏览器或移动文件可能影响访问，请定期导出备份。定位仅在你点击并授权后获取；导出的备份也包含地点，请妥善保管。</p><p><b>图片与许可</b>蕨叶封面来自 Unsplash；植物照片来自 Wikimedia Commons 与北卡罗来纳州立大学植物图鉴。桂花：Laitr Keiows（CC BY-SA 3.0）；菊花：Mokkie（CC BY-SA 3.0）；月季：Sakurai Midori（CC BY-SA 3.0）；樱花：Mark Kent（CC BY-SA 2.0）；白玉兰：Hideyuki KAMON（CC BY-SA 2.0）；荷花：Shin-改（公有领域）。图片经缩放与展示裁切，各照片遵循其原有许可。</p><div class="credit-links"><a href="https://unsplash.com" target="_blank" rel="noreferrer">Unsplash ↗</a><a href="https://commons.wikimedia.org/wiki/File:Osmanthus_fragrans_(orange_flowers).jpg" target="_blank" rel="noreferrer">桂花 · CC BY-SA 3.0 ↗</a><a href="https://commons.wikimedia.org/wiki/File:Yellow_chrysanthemum_flowers.jpg" target="_blank" rel="noreferrer">菊花 · CC BY-SA 3.0 ↗</a><a href="https://commons.wikimedia.org/wiki/File:Rosa_chinensis.jpg" target="_blank" rel="noreferrer">月季 · CC BY-SA 3.0 ↗</a><a href="https://plants.ces.ncsu.edu/plants/prunus-x-yedoensis/" target="_blank" rel="noreferrer">樱花 · Mark Kent ↗</a><a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noreferrer">CC BY-SA 3.0 ↗</a><a href="https://creativecommons.org/licenses/by-sa/2.0/" target="_blank" rel="noreferrer">CC BY-SA 2.0 ↗</a><a href="https://commons.wikimedia.org/wiki/File:Magnolia_denudata.jpg" target="_blank" rel="noreferrer">白玉兰 · CC BY-SA 2.0 ↗</a><a href="https://commons.wikimedia.org/wiki/File:Nelumbo_nucifera1.jpg" target="_blank" rel="noreferrer">荷花 · 公有领域 ↗</a></div></div>`;}
function renderModal(){if(!S.modal)return;$('#dialog').classList.toggle('wide-modal',S.modal==='upload');const fn={settings:settingsModal,location:locationModal,plant:plantModal,upload:uploadModal,record:recordModal,delete:deleteModal,about:aboutModal}[S.modal];$('#modal-content').innerHTML=modalClose()+fn();}
function syncUpload(){const u=S.upload;if(!u)return;for(const [id,key] of [['address','address'],['notes','notes'],['observed-at','observedAt'],['custom-name','customName']]){const field=$('#'+id);if(field){if(key==='address'&&u.address!==field.value)u.coordinates=null;u[key]=field.value;}}}
async function initDB(){try{S.db=await new Promise((resolve,reject)=>{const req=indexedDB.open('flora-notes-offline',1);const timer=setTimeout(()=>reject(new Error('timeout')),8000);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('observations'))req.result.createObjectStore('observations',{keyPath:'id'});};req.onsuccess=()=>{clearTimeout(timer);resolve(req.result);};req.onerror=()=>{clearTimeout(timer);reject(req.error);};req.onblocked=()=>{clearTimeout(timer);reject(new Error('blocked'));};});S.db.onversionchange=()=>S.db.close();const rows=await dbRead();S.records=rows.map(validateRecord).filter(Boolean).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));}catch{S.storageError='此浏览器未能启用本地数据库，暂不能持久保存。请用 Chrome 或 Edge 打开此 HTML，允许本地存储后重试。';S.db=null;}render();}
function dbRead(){return new Promise((resolve,reject)=>{const tx=S.db.transaction('observations','readonly');const req=tx.objectStore('observations').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbWrite(rows,remove=false){return new Promise((resolve,reject)=>{if(!S.db){reject(new Error('本地数据库不可用，请换用支持本地存储的浏览器。'));return;}const tx=S.db.transaction('observations','readwrite');const store=tx.objectStore('observations');rows.forEach(row=>remove?store.delete(row):store.put(row));tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('写入已取消'));});}
function validateRecord(r){if(!r||typeof r!=='object'||typeof r.id!=='string'||!/^[\w-]{4,100}$/.test(r.id)||typeof r.plantName!=='string'||!r.plantName.trim()||typeof r.address!=='string'||!r.address.trim()||typeof r.photo!=='string'||r.photo.length>15*1024*1024||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(r.photo)||!validDate(r.observedAt))return null;const number=v=>typeof v==='number'&&Number.isFinite(v);const coords=number(r.latitude)&&number(r.longitude)&&Math.abs(r.latitude)<=90&&Math.abs(r.longitude)<=180;return {id:r.id,plantId:PLANTS.some(p=>p.id===r.plantId)?r.plantId:null,plantName:r.plantName.trim().slice(0,150),scientificName:String(r.scientificName||'').slice(0,200),family:String(r.family||'').slice(0,200),bloomMonths:[...new Set((Array.isArray(r.bloomMonths)?r.bloomMonths:[]).filter(m=>Number.isInteger(m)&&m>=1&&m<=12))].sort((a,b)=>a-b),address:r.address.trim().slice(0,300),latitude:coords?r.latitude:null,longitude:coords?r.longitude:null,photo:r.photo,photoAddress:'indexeddb://flora-notes/observations/'+r.id,originalName:String(r.originalName||'plant.jpg').slice(0,250),method:['plantnet','deepseek'].includes(r.method)?r.method:'manual',confidence:r.method==='plantnet'&&number(r.confidence)&&r.confidence>=0&&r.confidence<=1?r.confidence:null,description:typeof r.description==='string'?r.description.slice(0,1500):'',features:typeof r.features==='string'?r.features.slice(0,1000):'',habitat:typeof r.habitat==='string'?r.habitat.slice(0,1000):'',reason:typeof r.reason==='string'?r.reason.slice(0,1000):'',model:typeof r.model==='string'?r.model.slice(0,120):'',notes:String(r.notes||'').slice(0,2000),observedAt:r.observedAt,createdAt:typeof r.createdAt==='string'&&!isNaN(Date.parse(r.createdAt))?r.createdAt:new Date().toISOString()};}
function validDate(s){if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(s+'T12:00:00Z');return !isNaN(d.getTime())&&d.toISOString().slice(0,10)===s;}
async function loadPhoto(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('请选择 JPG、PNG 或 WebP 格式的植物照片。');return;}if(file.size>10*1024*1024){toast('照片不能超过10MB，请压缩后重试。');return;}if(S.busy)return;syncUpload();S.busy=true;toast('正在整理这张植物照片…');try{const url=URL.createObjectURL(file);let img;try{img=await new Promise((resolve,reject)=>{const el=new Image();el.onload=()=>resolve(el);el.onerror=()=>reject(new Error('照片无法读取，请换一张有效的图片。'));el.src=url;});}finally{URL.revokeObjectURL(url);}if(img.naturalWidth*img.naturalHeight>60000000)throw new Error('图片分辨率过大，请缩小后再上传。');const scale=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');if(!ctx)throw new Error('浏览器无法处理照片。');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const photo=canvas.toDataURL('image/jpeg',.86);const u=S.upload||newUpload();Object.assign(u,{photo,originalName:file.name,width:canvas.width,height:canvas.height,candidates:[],candidate:null,resultProvider:null,resultModel:'',manual:true});S.upload=u;S.busy=false;openModal('upload');toast('照片已准备好；可识别，或手动选择植物保存。');}catch(e){S.busy=false;toast(e.message||'照片处理失败，请换一张照片。');}}
async function identify(){
  syncUpload();const u=S.upload;if(!u?.photo||S.busy)return;
  const provider=S.provider,config={...currentConfig()};
  if(!config.apiKey){showError('请在「识别接口」中填写 '+serviceName(provider)+' 的 API Key，或先手动选择植物保存。');return;}
  if(!navigator.onLine){showError('当前处于离线状态。识别需要联网，也可以手动记录植物。');return;}
  S.busy=true;S.error='';renderModal();
  try{
    const raw=await Recognition.identify(provider,config,u.photo);
    u.candidates=raw.map(c=>{const p=matchPlant(c.latin)||PLANTS.find(p=>p.name===c.name);return {...c,plantId:p?.id||null,name:p?.name||c.name,family:p?.family||c.family,months:p?.months||c.months,description:p?.description||c.description,features:p?.features||c.features,habitat:p?.habitat||c.habitat};});
    u.candidate=u.candidates[0];u.manual=false;u.resultProvider=provider;u.resultModel=provider==='deepseek'?config.model:'';
    S.services[provider].verified=true;toast(serviceName(provider)+' 已返回候选植物，请核实后保存。');
  }catch(e){S.error=e.message||'识别失败，请重试。';}
  finally{S.busy=false;renderModal();render();}
}
async function saveRecord(){syncUpload();const u=S.upload;if(S.busy||!u?.photo)return;const p=u.manual?PLANTS.find(p=>p.id===u.plantId):PLANTS.find(p=>p.id===u.candidate?.plantId),c=u.candidate;const name=u.manual?(p?.name||u.customName.trim()):c?.name;if(!name){showError('请填写植物名称。');return;}if(!u.address.trim()){showError('请填写发现地点，或选择一个已收录的公园。');$('#address')?.focus();return;}if(!validDate(u.observedAt)||u.observedAt>today()){showError('请填写不晚于今天的有效观察日期。');return;}if(!u.manual&&!c){showError('请选择一个识别候选，或切换手动记录。');return;}S.busy=true;S.error='';renderModal();try{const id=uid();const row=validateRecord({id,plantId:p?.id||null,plantName:name,scientificName:u.manual?(p?.latin||''):c.latin,family:u.manual?(p?.family||''):c.family,bloomMonths:u.manual?(p?.months||u.customMonths):c.months,address:u.address,latitude:u.coordinates?.lat??null,longitude:u.coordinates?.lng??null,photo:u.photo,originalName:u.originalName,method:u.manual?'manual':u.resultProvider||'plantnet',confidence:u.manual?null:c.score,description:u.manual?(p?.description||''):c.description,features:u.manual?(p?.features||''):c.features,habitat:u.manual?(p?.habitat||''):c.habitat,reason:u.manual?'':c.reason,model:u.manual?'':u.resultModel||'',notes:u.notes,observedAt:u.observedAt,createdAt:new Date().toISOString()});if(!row)throw new Error('记录内容无效，请检查照片和地点后重试。');await dbWrite([row]);S.records.unshift(row);S.upload=null;S.busy=false;closeModal();render();toast('植物手记已保存到本机，记得定期导出备份。');}catch(e){S.busy=false;S.error=e?.name==='QuotaExceededError'?'本机存储空间不足。请导出备份后清理部分记录，再重试。':(e.message||'本地保存失败，请稍后重试。');renderModal();}}
async function removeRecord(){if(S.busy)return;S.busy=true;renderModal();try{await dbWrite([S.selectedRecord],true);S.records=S.records.filter(r=>r.id!==S.selectedRecord);S.busy=false;closeModal();render();toast('已删除这条手记及照片。');}catch(e){S.busy=false;S.error=e.message||'删除失败，请重试。';renderModal();}}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportBackup(){if(!S.records.length)return;download(JSON.stringify({format:'flora-notes-backup',version:1,exportedAt:new Date().toISOString(),records:S.records},null,2),'花间手记备份-'+today()+'.json','application/json');toast('已导出备份，包含照片、植物信息和发现地点。');}
async function importBackup(file){if(!file)return;if(file.size>100*1024*1024){toast('备份超过100MB，请拆分后导入。');return;}if(!S.db){toast('本地数据库未启用，暂时无法导入。');return;}try{const data=JSON.parse(await file.text());if(data.format!=='flora-notes-backup'||data.version!==1||!Array.isArray(data.records)||data.records.length>1000)throw new Error('这不是有效的花间备份文件，或记录超过1000条。');const rows=data.records.map(validateRecord);if(rows.some(r=>!r))throw new Error('备份中存在无效记录，未导入任何内容。');const seen=new Set(S.records.map(r=>r.id));const added=[];for(const row of rows){if(!seen.has(row.id)){added.push(row);seen.add(row.id);}}if(!added.length){toast('这些记录已经存在，无需重复导入。');return;}await dbWrite(added);S.records=[...S.records,...added].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));go('records');toast(`已导入 ${added.length} 条手记（含照片），跳过 ${rows.length-added.length} 条重复记录。`);}catch(e){toast(e?.name==='QuotaExceededError'?'本机存储空间不足，导入已取消。':e.message||'备份读取失败。');}}
async function locate(forUpload){if(S.locating)return;if(!navigator.geolocation){showError('浏览器不支持定位，请手动选城或输入参考坐标。');return;}syncUpload();S.locating=true;S.error='';renderModal();navigator.geolocation.getCurrentPosition(pos=>{S.locating=false;const {latitude:lat,longitude:lng}=pos.coords;const city=CITIES.reduce((a,b)=>distance({lat,lng},a)<distance({lat,lng},b)?a:b);const isNearby=distance({lat,lng},city)<100;S.location={name:isNearby?city.name:'当前位置',lat,lng,exact:true};if(forUpload&&S.upload){S.upload.coordinates={lat,lng};S.upload.address=`定位地点（${lat.toFixed(5)}, ${lng.toFixed(5)}）`;renderModal();}else closeModal();render();toast('已获得参考位置，直线距离已更新。');},()=>{S.locating=false;S.error='未能获取位置。请检查浏览器定位权限；离线时可选择城市、已收录地点或手填参考坐标。';renderModal();},{timeout:10000,maximumAge:60000,enableHighAccuracy:true});}
function validateProxy(raw){if(!raw)return '';let url;try{url=new URL(raw);}catch{throw new Error('代理地址格式不正确。');}if(url.username||url.password||url.hash)throw new Error('代理地址不能包含账号、密码或片段。');if(url.protocol!=='https:'&&!(url.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(url.hostname)))throw new Error('请使用 HTTPS 代理，本机调试可使用 localhost。');return url.href;}
async function handleAction(el){const a=el.dataset.action;if(S.busy&&!['dismiss-toast'].includes(a))return;switch(a){
case 'nav':go(el.dataset.tab);break;
case 'open-menu':$('#sidebar').classList.add('open');$('#mobile-backdrop').hidden=false;updateMenuAccess();break;
case 'close-menu':closeMenu();break;
case 'dismiss-toast':$('#toast').hidden=true;break;
case 'upload':openModal('upload');break;
case 'choose-photo':syncUpload();$('#photo-input').click();break;
case 'settings':syncUpload();openModal('settings');break;
case 'about':openModal('about');break;
case 'location':openModal('location');break;
case 'close-modal':syncUpload();closeModal();break;
case 'month':S.month=Number(el.dataset.month);render();break;
case 'prev-month':if(--S.month<1){S.month=12;S.year--;}render();break;
case 'next-month':if(++S.month>12){S.month=1;S.year++;}render();break;
case 'plant':S.selectedPlant=el.dataset.id;openModal('plant');break;
case 'find-plant':S.plantFilter=el.dataset.id;S.onlySaved=false;closeModal();go('map');break;
case 'place':S.selectedPlace=el.dataset.id;if(S.tab!=='map')go('map');else render();break;
case 'city':S.location={...CITIES.find(c=>c.name===el.dataset.city),exact:false};try{localStorage.setItem('flora-location-v1',JSON.stringify({name:S.location.name}));}catch{}closeModal();render();toast('已切换至'+S.location.name+'，按市中心估算距离。');break;
case 'locate':locate(false);break;
case 'locate-upload':locate(true);break;
case 'identify':await identify();break;
case 'manual':syncUpload();S.upload.manual=true;S.error='';renderModal();break;
case 'candidate':syncUpload();S.upload.candidate=S.upload.candidates[Number(el.dataset.index)];renderModal();break;
case 'custom-month':{syncUpload();const m=Number(el.dataset.month),ms=S.upload.customMonths;S.upload.customMonths=ms.includes(m)?ms.filter(x=>x!==m):[...ms,m];renderModal();break;}
case 'save-record':await saveRecord();break;
case 'record':S.selectedRecord=el.dataset.id;openModal('record');break;
case 'delete':S.selectedRecord=el.dataset.id;openModal('delete');break;
case 'confirm-delete':await removeRecord();break;
case 'find-record':{const r=S.records.find(r=>r.id===el.dataset.id);if(r.latitude!=null&&r.longitude!=null)S.location={name:r.address.length>10?r.address.slice(0,10)+'…':r.address,lat:r.latitude,lng:r.longitude,exact:true};S.plantFilter=r.plantId||'all';S.onlySaved=false;closeModal();go('map');if(!r.plantId)toast('该植物尚未匹配地点库，当前显示附近已收录的当季植物。');else if(r.latitude==null)toast('手填地点未附坐标，当前按已选参考位置计算距离。');break;}
case 'download-photo':{const r=S.records.find(r=>r.id===el.dataset.id);const a=document.createElement('a');a.href=r.photo;a.download=r.plantName+'-'+r.observedAt+'.jpg';document.body.append(a);a.click();a.remove();break;}
case 'export':exportBackup();break;
case 'import':$('#backup-input').click();break;
}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();handleAction(el).catch(err=>{console.error('操作失败',err?.name);toast('操作未完成，请重试。');});}});
document.addEventListener('input',e=>{if(e.target.id==='plant-search'){S.query=e.target.value;$('#library-grid').innerHTML=plantResults();}if(e.target.id==='record-search'){S.query=e.target.value;$('#record-grid').innerHTML=recordResults();}});
document.addEventListener('change',e=>{const el=e.target;switch(el.id){case 'api-provider':captureSettingsDraft();S.settingsDraft.provider=el.value;S.error='';renderModal();break;case 'photo-input':loadPhoto(el.files[0]);el.value='';break;case 'backup-input':importBackup(el.files[0]);el.value='';break;case 'filter-plant':S.plantFilter=el.value;render();break;case 'filter-month':S.month=Number(el.value);render();break;case 'filter-radius':S.radius=Number(el.value);render();break;case 'only-saved':S.onlySaved=el.checked;render();break;case 'manual-plant':syncUpload();S.upload.plantId=el.value;renderModal();break;case 'known-place':{syncUpload();const p=PLACES.find(p=>p.id===el.value);if(p){S.upload.address=p.address+' · '+p.name;S.upload.coordinates={lat:p.lat,lng:p.lng};renderModal();}break;}case 'address':syncUpload();break;}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='settings-form'){try{applySettings();}catch(err){showError(err.message);}}if(e.target.id==='coordinate-form'){const lat=Number($('#latitude').value),lng=Number($('#longitude').value),name=$('#custom-location').value.trim()||'自定位置';if(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180){showError('请输入有效的经纬度。');return;}S.location={name:name.slice(0,50),lat,lng,exact:true};closeModal();render();toast('已应用参考坐标，距离已重新计算。');}});
$('#dialog').addEventListener('cancel',e=>{if(S.busy)e.preventDefault();else{syncUpload();S.modal=null;S.error='';}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){syncUpload();closeModal();}});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-drop-zone]')){e.preventDefault();e.target.closest('[data-drop-zone]').classList.add('dragging');}});
document.addEventListener('dragleave',e=>{e.target.closest('[data-drop-zone]')?.classList.remove('dragging');});
document.addEventListener('drop',e=>{const zone=e.target.closest('[data-drop-zone]');if(zone){e.preventDefault();zone.classList.remove('dragging');loadPhoto(e.dataTransfer.files[0]);}else if(e.dataTransfer?.files?.length)e.preventDefault();});
matchMedia('(max-width:680px)').addEventListener('change',updateMenuAccess);
updateMenuAccess();render();initDB();
})();
